import{_ as t,o,c as d,a2 as a}from"./chunks/framework.CRfKVJQk.js";const p=JSON.parse('{"title":"Troubleshooting","description":"Fix common Liquid Glass problems in React Native, Expo and web apps: flat glass on Android, Expo Go fallback, web build errors and performance issues.","frontmatter":{"description":"Fix common Liquid Glass problems in React Native, Expo and web apps: flat glass on Android, Expo Go fallback, web build errors and performance issues.","head":[["link",{"rel":"canonical","href":"https://sachinmeenasipl.github.io/react-native-glass-effect/reference/troubleshooting"}],["meta",{"property":"og:url","content":"https://sachinmeenasipl.github.io/react-native-glass-effect/reference/troubleshooting"}],["meta",{"property":"og:title","content":"Troubleshooting · Liquid Glass for React Native"}],["meta",{"property":"og:description","content":"Fix common Liquid Glass problems in React Native, Expo and web apps: flat glass on Android, Expo Go fallback, web build errors and performance issues."}],["meta",{"name":"twitter:title","content":"Troubleshooting · Liquid Glass for React Native"}],["meta",{"name":"twitter:description","content":"Fix common Liquid Glass problems in React Native, Expo and web apps: flat glass on Android, Expo Go fallback, web build errors and performance issues."}]]},"headers":[],"relativePath":"reference/troubleshooting.md","filePath":"reference/troubleshooting.md"}'),r={name:"reference/troubleshooting.md"};function s(i,e,n,l,c,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Find your symptom by area. Each row says what causes it, how to fix it, and how to check the fix.</p><p>First step on Android: <code>adb logcat -s LiquidGlass</code>. Most setup problems print a one-line explanation there.</p><h2 id="installation-and-builds" tabindex="-1">Installation and builds <a class="header-anchor" href="#installation-and-builds" aria-label="Permalink to &quot;Installation and builds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th><th>How to check</th></tr></thead><tbody><tr><td>Warning &quot;Native code not found, rendering a plain fallback&quot;</td><td>The app wasn&#39;t rebuilt after installing, or it&#39;s running in Expo Go</td><td>Rebuild: <code>npx react-native run-android</code> / <code>run-ios</code> (after <code>pod install</code>), or <code>npx expo run:android</code> / <code>run:ios</code></td><td><code>useGlassCapabilities().isNativeAvailable</code> is <code>true</code></td></tr><tr><td><code>isNativeAvailable</code> is <code>false</code> on a phone</td><td>Same as above, or the New Architecture is off</td><td>Rebuild; turn on the New Architecture (<code>newArchEnabled=true</code> in <code>android/gradle.properties</code>)</td><td>See <a href="/react-native-glass-effect/installation/verify">Verify the install</a></td></tr><tr><td><code>pod install</code> fails: the deployment target is too low</td><td>The library needs iOS 15.1</td><td>Set <code>platform :ios, &#39;15.1&#39;</code> (or higher) in <code>ios/Podfile</code>, then <code>pod install</code></td><td><code>pod install</code> completes</td></tr><tr><td>Metro: &quot;Unable to resolve module react-native-liquid-glass-native&quot;</td><td>The package isn&#39;t installed in this app, or Metro&#39;s cache is stale</td><td><code>npm install react-native-liquid-glass-native</code>, then <code>npx react-native start --reset-cache</code> (or <code>npx expo start --clear</code>)</td><td>The bundle builds</td></tr><tr><td>&quot;Invalid hook call&quot; when the library is linked from a local folder</td><td>A second copy of React is loaded from the library&#39;s own <code>node_modules</code></td><td>Resolve <code>react</code>, <code>react-native</code> and the library from your app. See <a href="/react-native-glass-effect/installation/expo#using-the-library-from-a-monorepo-or-a-local-folder">Expo → local folder</a></td><td>The warning is gone</td></tr><tr><td>Windows, Android build: <code>ninja: error: mkdir(...): No such file or directory</code></td><td>A file path longer than 260 characters (a project in a deep folder such as OneDrive)</td><td>Enable Windows long paths, or set a short CMake <code>buildStagingDirectory</code>. See <a href="/react-native-glass-effect/installation/expo#windows-android-build-fails-with-ninja-no-such-file-or-directory">Expo → Windows</a></td><td>The Gradle build passes</td></tr></tbody></table><h2 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to &quot;Android&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th><th>How to check</th></tr></thead><tbody><tr><td>Glass is a flat, solid colour</td><td>No <code>GlassBackdrop</code> behind it, or the glass is <strong>inside</strong> one</td><td>Wrap the background in <code>&lt;GlassBackdrop&gt;</code> and render glass next to it. See <a href="/react-native-glass-effect/guide/core-concepts">Core concepts</a></td><td>logcat no longer prints the backdrop warning; <code>getGlassStats().solidDraws</code> is 0</td></tr><tr><td>Solid colour only inside a Modal</td><td>A Modal is a separate window</td><td>Add a <code>GlassBackdrop</code> inside the Modal. See <a href="/react-native-glass-effect/recipes/modal">Glass in a modal</a></td><td>The glass in the modal blurs</td></tr><tr><td>Part of the glass looks empty, tint only</td><td>The glass extends past its backdrop</td><td>Make the backdrop cover the glass (<code>StyleSheet.absoluteFill</code>)</td><td>The whole glass blurs</td></tr><tr><td>No blur on Android 11 and older, only a solid colour</td><td>Images loaded as HARDWARE bitmaps can&#39;t be captured in software</td><td>Glide: <code>.disallowHardwareConfig()</code>; Coil: <code>allowHardware(false)</code>, for images behind glass</td><td><code>getGlassStats().compatCaptures</code> increases when the image changes</td></tr><tr><td>Video or map behind glass shows black or transparent</td><td>It renders into a <code>SurfaceView</code></td><td>Use texture mode (for example <code>useTextureView</code> in react-native-video)</td><td>The video shows through the glass</td></tr><tr><td>Looks flat on Android 12</td><td>No refraction below Android 13, by design</td><td>Raise <code>illumination</code> or <code>borderOpacity</code> for more definition</td><td><code>bestRenderer</code> is <code>blur</code></td></tr><tr><td>The shader never shows on one device model</td><td>The GPU driver rejected the shader; the glass fell back to blur</td><td>Nothing to do: it&#39;s automatic. Please report the device model</td><td><code>getGlassStats().shaderPasses</code> stays 0</td></tr><tr><td>Glass doesn&#39;t follow a rotated parent (Android 7–9)</td><td>Rotation and scale alignment need Android 10+</td><td>Avoid rotating glass on old Android</td><td>—</td></tr><tr><td>logcat: &quot;Could not find generated setter for class …LiquidGlassViewManager&quot;</td><td>Known log message on React Native 0.88</td><td>None needed: the glass renders and props apply. See <a href="/react-native-glass-effect/reference/changelog#known-issues">Known issues</a></td><td>—</td></tr><tr><td>A full-screen <code>&lt;Image&gt;</code> in the backdrop looks zoomed or doesn&#39;t fill the screen</td><td>An image positioned only with <code>absoluteFill</code> can draw at its natural size on Android</td><td>Give it an explicit size: <code>width: &#39;100%&#39;, height: &#39;100%&#39;</code></td><td>The image fills the backdrop</td></tr></tbody></table><h2 id="ios" tabindex="-1">iOS <a class="header-anchor" href="#ios" aria-label="Permalink to &quot;iOS&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th><th>How to check</th></tr></thead><tbody><tr><td>No Liquid Glass on iOS 26, only a blur material</td><td>The app was built with Xcode older than 26</td><td>Build with Xcode 26</td><td><code>bestRenderer</code> is <code>system-glass</code></td></tr><tr><td>Glass looks different from Android</td><td>iOS uses Apple&#39;s glass by default</td><td>Use <code>FrostedGlass</code> or <code>iosRenderer=&quot;shader&quot;</code>. See <a href="/react-native-glass-effect/features/ios-renderers">iOS renderers</a></td><td>Both platforms look alike</td></tr><tr><td><code>iosRenderer=&quot;shader&quot;</code> looks like plain system glass</td><td>No <code>GlassBackdrop</code> behind the glass</td><td>Add a backdrop. Xcode&#39;s console prints a &quot;found no GlassBackdrop&quot; message</td><td>The shader glass appears</td></tr><tr><td>Blur looks wrong while fading glass in or out</td><td>UIKit can&#39;t draw blur correctly at <code>opacity</code> below 1</td><td>Fade the content inside the glass, or scale the glass instead</td><td>—</td></tr><tr><td><code>blur</code>, <code>intensity</code> or <code>lightAngle</code> have no effect on iOS 26</td><td>Apple draws the system glass and decides these</td><td>Expected. Use <code>iosRenderer=&quot;shader&quot;</code> for full control</td><td>—</td></tr></tbody></table><h2 id="expo" tabindex="-1">Expo <a class="header-anchor" href="#expo" aria-label="Permalink to &quot;Expo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th><th>How to check</th></tr></thead><tbody><tr><td>A plain tinted box, no blur, in Expo Go</td><td>Expo Go can&#39;t load third-party native code</td><td>Use a dev build: <code>npx expo run:android</code> / <code>run:ios</code>, or EAS Build</td><td><code>isNativeAvailable</code> is <code>true</code> in the dev build</td></tr><tr><td>Changes in <code>android/</code> disappear</td><td><code>npx expo prebuild --clean</code> regenerates the native folders</td><td>Make native changes with a config plugin, or re-apply them after prebuild</td><td>—</td></tr></tbody></table><h2 id="web" tabindex="-1">Web <a class="header-anchor" href="#web" aria-label="Permalink to &quot;Web&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th><th>How to check</th></tr></thead><tbody><tr><td>Build fails: <code>Could not load react-native/Libraries/...</code></td><td><code>react-native</code> isn&#39;t aliased to <code>react-native-web</code></td><td>Add the alias. See <a href="/react-native-glass-effect/installation/web">Web</a> or <a href="/react-native-glass-effect/installation/nextjs">Next.js</a></td><td>The build passes</td></tr><tr><td><code>global is not defined</code> in the browser (Vite)</td><td>A dependency expects Node&#39;s <code>global</code></td><td>Add <code>define: { global: &#39;globalThis&#39; }</code> to <code>vite.config.js</code></td><td>No console error</td></tr><tr><td>The page is blank, or content collapses to the top</td><td>The root element has no height</td><td>Vite: a full-height flex root. Next.js: <code>height: &#39;100vh&#39;</code> on <code>&lt;body&gt;</code></td><td>Screens fill the window</td></tr><tr><td>Next.js: &quot;You&#39;re importing a component that needs useState&quot;</td><td>A glass component is used from a server component file</td><td>Add <code>&#39;use client&#39;</code> to the file that uses glass</td><td>The build passes</td></tr><tr><td>No blur, only tint</td><td>The browser doesn&#39;t support <code>backdrop-filter</code>, or an ancestor (with <code>opacity</code> below 1, <code>filter</code>, <code>mask</code> or <code>will-change</code>) limits what the glass can blur</td><td>Expected in old browsers. Otherwise move those styles off the glass&#39;s ancestors</td><td>The blur appears</td></tr><tr><td>Refraction or touch light don&#39;t show</td><td>They have no CSS equivalent</td><td>Expected on the web</td><td>—</td></tr></tbody></table><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th><th>How to check</th></tr></thead><tbody><tr><td>Stutters while an animation plays <strong>under</strong> a glass</td><td>Glass over changing content redraws every frame</td><td>Move the animation, use a smaller blur, or <code>quality=&quot;low&quot;</code></td><td><code>getGlassStats().gpuBlurPasses</code> drops while idle</td></tr><tr><td>Stutters while scrolling on older phones</td><td>Too many glass views, or the compat tier</td><td><code>quality=&quot;low&quot;</code> or <code>&quot;static&quot;</code>, fewer or smaller glass views</td><td><code>adb shell dumpsys gfxinfo &lt;package&gt; framestats</code></td></tr><tr><td>Squish and transitions don&#39;t animate</td><td>Reduce Motion / Remove animations is on</td><td>Expected (accessibility)</td><td>—</td></tr></tbody></table><p>More: <a href="/react-native-glass-effect/features/performance">Performance</a>.</p><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck?&quot;">​</a></h2><p><a href="https://github.com/SachinMeenaSipl/react-native-glass-effect/issues" target="_blank" rel="noreferrer">Open an issue</a> with: your React Native or Expo version, the device and OS version (or browser), the <code>useGlassCapabilities()</code> output, and the <code>LiquidGlass</code> logcat lines on Android.</p>',18)])])}const b=t(r,[["render",s]]);export{p as __pageData,b as default};
